<script setup lang="ts">
import{onMounted}from'vue';import{storeToRefs}from'pinia';import{useRoute}from'vue-router';import FinanceSubnav from'../components/FinanceSubnav.vue';import{useFinanceStore}from'../runtime/finance-store';import'./finance-views.css'
const store=useFinanceStore(),route=useRoute();const{detail,loading,error}=storeToRefs(store);const money=(v:number)=>`¥${(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;const kindLabel={receipt:'收款',payment:'付款','transfer-in':'转入','transfer-out':'转出',refund:'退款','other-income':'其他收入','other-expense':'其他支出',prototype:'原型演示'}as const;onMounted(()=>store.loadDetail(String(route.params.accountId),String(route.query.month??'2026-08')))
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>账户收支明细</h1><p>确认后的流水不可编辑或删除；未知业务来源不生成死链接。</p></div></header><FinanceSubnav/><div v-if="error" class="finance-state error">{{error}}</div><div v-else-if="loading" class="finance-state">正在加载账户明细…</div><template v-else-if="detail"><div class="finance-summary"><article><span>账户 / 期间</span><strong>{{detail.account.name}}</strong><small>{{detail.month}} · {{detail.account.status==='enabled'?'启用':'停用'}}</small></article><article><span>期初余额</span><strong>{{money(detail.openingBalanceCents)}}</strong></article><article><span>本期收入 / 支出</span><strong>{{money(detail.periodIncomeCents)}} / {{money(detail.periodExpenseCents)}}</strong></article><article><span>期末余额</span><strong>{{money(detail.closingBalanceCents)}}</strong></article></div><p v-if="detail.bank" class="finance-panel">关联银行：{{detail.bank.bankName}} · {{detail.bank.bankAccount}}</p><div v-if="!detail.movements.length" class="finance-state">本期暂无收支流水</div><div v-else class="finance-table-wrap"><table class="finance-table"><thead><tr><th>日期</th><th>账户名称</th><th>单据类型</th><th>单据号</th><th>往来单位</th><th class="fin-money">收入</th><th class="fin-money">支出</th><th class="fin-money">操作后余额</th><th>摘要</th></tr></thead><tbody><tr v-for="item in detail.movements" :key="item.id"><td>{{item.occurredAt.slice(0,16).replace('T',' ')}}</td><td>{{detail.account.name}}</td><td>{{kindLabel[item.kind]}}</td><td>{{item.sourceNoSnapshot}}<small>来源尚未接入</small></td><td>{{item.counterpartySnapshot??'—'}}</td><td class="fin-money fin-income">{{item.direction==='income'?money(item.amountCents):'—'}}</td><td class="fin-money fin-expense">{{item.direction==='expense'?money(item.amountCents):'—'}}</td><td class="fin-money">{{money(item.balanceAfterCents)}}</td><td>{{item.summary}}</td></tr></tbody></table></div></template></section></template>
